\min_{\mathcal{E}} & \quad \|\mathcal{H}_{spa}(\mathcal{E} \times_3 \mathbf{D}_{\mathcal{E}}) - (\mathcal{Y}_R - \mathcal{H}_{spa}(\mathcal{L}^{k+1} \times_3 \mathbf{D}_{\mathcal{L}}))\|_F^2 + \|\mathcal{H}_{spec}(\mathcal{E} \times_3 \mathbf{D}_{\mathcal{E}}) - (\mathcal{Z} - \mathcal{H}_{spec}(\mathcal{L}^{k+1} \times_3 \mathbf{D}_{\mathcal{L}}))\|_F^2 \\
& + \beta \|\mathcal{E}\|_{l_F^{\psi}} + \frac{\lambda}{2} \|\mathcal{E} - \mathcal{E}^k\|_F^2,
\end{split}
\tag{30}
\end{equation}
$$

